fn main() {
    println!("Hello, world!");
}

use std::io::{self, stdout};

use crossterm::{
    event::{self, Event, KeyCode, KeyEventKind},
    execute,
    terminal::{disable_raw_mode, enable_raw_mode, EnterAlternateScreen, LeaveAlternateScreen},
};
use ratatui::{
    backend::CrosstermBackend,
    layout::Alignment,
    style::{Color, Style},
    widgets::{Block, Borders, Paragraph},
    Terminal,
};

fn main() -> io::Result<()> {
    // 1. 初始化終端機 (啟用 Raw Mode 並切換至 AlternateScreen)
    enable_raw_mode()?;
    let mut stdout = stdout();
    execute!(stdout, EnterAlternateScreen)?;
    let backend = CrosstermBackend::new(stdout);
    let mut terminal = Terminal::new(backend)?;

    // 2. 執行主迴圈
    let app_result = run_app(&mut terminal);

    // 3. 還原終端機狀態 (停用 Raw Mode 並離開 AlternateScreen)
    disable_raw_mode()?;
    execute!(terminal.backend_mut(), LeaveAlternateScreen)?;
    terminal.show_cursor()?;

    app_result
}

fn run_app(terminal: &mut Terminal<CrosstermBackend<std::io::Stdout>>) -> io::Result<()> {
    loop {
        terminal.draw(|f| {
            let area = f.area();

            let block = Block::default()
                .title(" Ratatui TUI Demo ")
                .title_alignment(Alignment::Center)
                .borders(Borders::ALL)
                .style(Style::default().fg(Color::Cyan));

            let paragraph = Paragraph::new("\nHello Ratatui! Press 'q' or 'Esc' to exit.")
                .alignment(Alignment::Center)
                .block(block);

            f.render_widget(paragraph, area);
        })?;

        // 監聽鍵盤事件
        if let Event::Key(key) = event::read()? {
            if key.kind == KeyEventKind::Press {
                match key.code {
                    KeyCode::Char('q') | KeyCode::Esc => return Ok(()),
                    _ => {}
                }
            }
        }
    }
}

