}

fn render_kpis(f: &mut Frame, app: &App, area: Rect) {
    let kpi_chunks = Layout::default()
        .direction(Direction::Horizontal)
        .constraints([
            Constraint::Percentage(20),
            Constraint::Percentage(20),
            Constraint::Percentage(30),
            Constraint::Percentage(30),
        ])
        .split(area);

    // 1. Closets KPI
    let closet_block = Block::default()
        .borders(Borders::ALL)
        .border_type(BorderType::Rounded)
        .title(" IDF Closets ")
        .title_style(Style::default().fg(Color::Cyan).add_modifier(Modifier::BOLD));
    let closet_text = vec![
        Line::from(vec![
            Span::styled(format!(" {} ", app.net.total_closets()), Style::default().fg(Color::White).add_modifier(Modifier::BOLD)),
            Span::raw("Active Closets"),
        ]),
        Line::from(vec![
            Span::styled(" ● ", Style::default().fg(Color::Green)),
            Span::raw(format!("{} Online", app.net.closets.iter().filter(|c| c.status() == DeviceStatus::Online).count())),
            Span::styled("  ▲ ", Style::default().fg(Color::Yellow)),
            Span::raw(format!("{} Degraded", app.net.closets.iter().filter(|c| c.status() != DeviceStatus::Online).count())),
        ]),
    ];
    f.render_widget(Paragraph::new(closet_text).block(closet_block), kpi_chunks[0]);

    // 2. Switches KPI
    let switch_block = Block::default()
        .borders(Borders::ALL)
        .border_type(BorderType::Rounded)
        .title(" Network Switches ")
        .title_style(Style::default().fg(Color::Cyan).add_modifier(Modifier::BOLD));
    let total_switches = app.net.total_switches();
    let degraded_switches = app.net.closets.iter()
        .flat_map(|c| &c.racks)
        .flat_map(|r| &r.switches)
        .filter(|s| s.status != DeviceStatus::Online)
        .count();
    let switch_text = vec![
        Line::from(vec![
            Span::styled(format!(" {} ", total_switches), Style::default().fg(Color::White).add_modifier(Modifier::BOLD)),
            Span::raw("Managed Units"),
        ]),
        Line::from(vec![
            Span::styled(format!(" {} Online", total_switches - degraded_switches), Style::default().fg(Color::Green)),
            Span::styled(format!("  {} Attention", degraded_switches), Style::default().fg(if degraded_switches > 0 { Color::Yellow } else { Color::DarkGray })),
        ]),
    ];
    f.render_widget(Paragraph::new(switch_text).block(switch_block), kpi_chunks[1]);

    // 3. Interfaces KPI
    let iface_block = Block::default()
        .borders(Borders::ALL)
        .border_type(BorderType::Rounded)
        .title(" Port Capacity ")
        .title_style(Style::default().fg(Color::Cyan).add_modifier(Modifier::BOLD));
    let total_ifaces = app.net.total_interfaces();
    let active_ifaces = app.net.active_interfaces();
    let err_ifaces = app.net.err_interfaces();
    let down_ifaces = total_ifaces.saturating_sub(active_ifaces + err_ifaces);
    let iface_text = vec![
        Line::from(vec![
            Span::styled(format!(" {} ", total_ifaces), Style::default().fg(Color::White).add_modifier(Modifier::BOLD)),
            Span::raw("Total Switch Ports"),
        ]),
        Line::from(vec![
            Span::styled(format!("● Up: {} ", active_ifaces), Style::default().fg(Color::Green)),
            Span::styled(format!("○ Down: {} ", down_ifaces), Style::default().fg(Color::DarkGray)),
            Span::styled(format!("✖ ErrDis: {}", err_ifaces), Style::default().fg(if err_ifaces > 0 { Color::Red } else { Color::Green })),
        ]),
    ];
    f.render_widget(Paragraph::new(iface_text).block(iface_block), kpi_chunks[2]);

    // 4. PoE Consumption Gauge KPI
    let poe_draw = app.net.total_poe_draw();
    let poe_budget = app.net.total_poe_budget();
    let poe_pct = if poe_budget > 0.0 {
        ((poe_draw / poe_budget) * 100.0).clamp(0.0, 100.0) as u16
    } else {
        0
    };
    let poe_block = Block::default()
        .borders(Borders::ALL)
        .border_type(BorderType::Rounded)
        .title(" Campus PoE Draw ")
        .title_style(Style::default().fg(Color::Cyan).add_modifier(Modifier::BOLD));
    let poe_gauge = Gauge::default()
        .block(poe_block)
        .gauge_style(Style::default().fg(if poe_pct > 80 { Color::Red } else if poe_pct > 60 { Color::Yellow } else { Color::Green }))
        .percent(poe_pct)
        .label(format!("{:.1}W / {:.0}W ({}%)", poe_draw, poe_budget, poe_pct));
    f.render_widget(poe_gauge, kpi_chunks[3]);
}

