        Line::from(vec![
            Span::styled("Oper Status:     ", Style::default().fg(Color::DarkGray)),
            Span::styled(status_str, status_style),
        ]),
        Line::from(vec![
            Span::styled("Description:     ", Style::default().fg(Color::DarkGray)),
            Span::styled(&port.description, Style::default().fg(Color::Yellow)),
        ]),
        Line::from(""),
        Line::from(vec![
            Span::styled("--- LAYER 2 / SWITCHING CONFIGURATION ---", Style::default().fg(Color::Cyan)),
        ]),
        Line::from(vec![
            Span::styled("Switchport Mode: ", Style::default().fg(Color::DarkGray)),
            Span::styled(port.mode.as_str(), Style::default().fg(Color::White)),
            Span::styled("   VLAN Assignment: ", Style::default().fg(Color::DarkGray)),
            Span::styled(format!("{} ({})", port.vlan, port.vlan_name), Style::default().fg(Color::White)),
        ]),
        Line::from(vec![
            Span::styled("Speed / Duplex:  ", Style::default().fg(Color::DarkGray)),
            Span::styled(format!("{} / {}", port.speed, port.duplex), Style::default().fg(Color::White)),
            Span::styled("   MTU Size: ", Style::default().fg(Color::DarkGray)),
            Span::styled(format!("{} bytes", port.mtu), Style::default().fg(Color::White)),
        ]),
        Line::from(vec![
            Span::styled("Learned MAC:     ", Style::default().fg(Color::DarkGray)),
            Span::styled(mac_str, Style::default().fg(Color::LightCyan)),
        ]),
        Line::from(""),
        Line::from(vec![
            Span::styled("--- POWER OVER ETHERNET (PoE) ---", Style::default().fg(Color::Cyan)),
        ]),
        Line::from(vec![
            Span::styled("PoE Status:      ", Style::default().fg(Color::DarkGray)),
            Span::styled(poe_str, Style::default().fg(if port.poe_enabled { Color::Green } else { Color::DarkGray })),
        ]),
        Line::from(""),
        Line::from(vec![
            Span::styled("--- TRAFFIC TELEMETRY & ERROR COUNTERS ---", Style::default().fg(Color::Cyan)),
        ]),
        Line::from(vec![
            Span::styled("Rx Throughput:   ", Style::default().fg(Color::DarkGray)),
            Span::styled(format!("{:.2} MB ({} bytes)", rx_mb, port.rx_bytes), Style::default().fg(Color::White)),
        ]),
        Line::from(vec![
            Span::styled("Tx Throughput:   ", Style::default().fg(Color::DarkGray)),
            Span::styled(format!("{:.2} MB ({} bytes)", tx_mb, port.tx_bytes), Style::default().fg(Color::White)),
