            .block(res_block);
        f.render_widget(p, chunks[1]);
    } else {
        let items: Vec<ListItem> = app
            .search_results
            .iter()
            .enumerate()
            .map(|(idx, res)| {
                let is_selected = idx == app.search_cursor;
                let style = if is_selected {
                    Style::default().bg(Color::Rgb(30, 45, 75)).add_modifier(Modifier::BOLD)
                } else {
                    Style::default()
                };

                let marker = if is_selected { "► " } else { "  " };

                let line = Line::from(vec![
                    Span::styled(marker, Style::default().fg(Color::Yellow)),
                    Span::styled(&res.title, Style::default().fg(Color::White).add_modifier(Modifier::BOLD)),
                    Span::styled(format!("  —  {}", res.subtitle), Style::default().fg(Color::Gray)),
                ]);

                ListItem::new(line).style(style)
            })
            .collect();

        let list = List::new(items).block(res_block);
        f.render_widget(list, chunks[1]);
    }

    // Hint footer
    let hint = Paragraph::new("Press Enter to jump to target switch/port | Esc to close search")
        .style(Style::default().fg(Color::DarkGray));
    f.render_widget(hint, chunks[2]);
}

