        mac: if mac.is_empty() { "00:00:00:00:00:00".to_string() } else { mac },
    })
}

/// Parses the output of `show interfaces status` on Cisco Catalyst 9300.
pub fn parse_show_interfaces_status(output: &str) -> Result<Vec<CiscoInterfaceStatus>, ParseError> {
    if output.trim().is_empty() {
        return Err(ParseError::EmptyOutput);
    }

    let mut list = Vec::new();
    let mut header_seen = false;

    for line in output.lines() {
        let trimmed = line.trim();
        if trimmed.starts_with("Port ") && trimmed.contains("Status") {
            header_seen = true;
            continue;
        }

        if !header_seen || trimmed.is_empty() {
            continue;
        }

        // Fixed columns in `show interfaces status`:
        if line.len() >= 30 {
            let port = line.get(0..10.min(line.len())).unwrap_or("").trim().to_string();
            let name = if line.len() >= 29 { line[10..29].trim().to_string() } else { String::new() };
            let status = if line.len() >= 42 { line[29..42].trim().to_string() } else { String::new() };
            let vlan = if line.len() >= 53 { line[42..53].trim().to_string() } else { "1".to_string() };
            let duplex = if line.len() >= 61 { line[53..61].trim().to_string() } else { "auto".to_string() };
            let speed = if line.len() >= 68 { line[61..68].trim().to_string() } else { "auto".to_string() };
            let media_type = if line.len() > 68 { line[68..].trim().to_string() } else { String::new() };

            if !port.is_empty() {
                list.push(CiscoInterfaceStatus {
                    port,
                    name,
                    status,
                    vlan,
                    duplex,
                    speed,
                    media_type,
                });
            }
        } else {
            let parts: Vec<&str> = trimmed.split_whitespace().collect();
            if parts.len() >= 6 {
                list.push(CiscoInterfaceStatus {
                    port: parts[0].to_string(),
                    name: String::new(),
                    status: parts[1].to_string(),
                    vlan: parts[2].to_string(),
                    duplex: parts[3].to_string(),
                    speed: parts[4].to_string(),
                    media_type: parts.get(5).unwrap_or(&"").to_string(),
                });
            }
        }
    }

    Ok(list)
}

