pub fn sync_selected_switch(&mut self) {
    let (c, r, s) = self.selected_switch;
    let is_cisco = self
        .net
        .closets
        .get(c)
        .and_then(|closet| closet.racks.get(r))
        .and_then(|rack| rack.switches.get(s))
        .map(|sw| sw.vendor.eq_ignore_ascii_case("Cisco"))
        .unwrap_or(false);

    if !is_cisco {
        let vendor = self.current_switch().map(|sw| sw.vendor.as_str()).unwrap_or("Unknown");
        self.notification = Some(Notification {
            message: format!("Device vendor '{vendor}' is not Cisco IOS-XE. Milestone 2 provides read-only Cisco integration."),
            level: NotificationLevel::Warning,
        });
        return;
    }

    let (target, host) = {
        let sw = match self.current_switch() {
            Some(sw) => sw,
            None => return,
        };
        let creds = crate::provider::DeviceCredentials::with_password(
            "admin",
            crate::provider::CredentialRef::from_secret("CiscoSecret123"),
        );
        let policy = crate::provider::HostKeyPolicy::AcceptNew {
            known_hosts: Vec::new(),
        };
        let target = crate::provider::DeviceTarget::new(
            sw.id.clone(),
            sw.hostname.clone(),
            sw.ip.clone(),
            creds,
            policy,
        );
        (target, sw.hostname.clone())
    };

    if let Some(sw) = self.net.closets.get_mut(c).and_then(|cl| cl.racks.get_mut(r)).and_then(|rk| rk.switches.get_mut(s)) {
        match self.cisco_provider.sync_switch(&target, sw) {
            Ok(()) => {
                self.notification = Some(Notification {
                    message: format!("Successfully synced read-only telemetry for {host} via SSH ({} ports, CPU {}%, Temp {}°C)", sw.interfaces.len(), sw.cpu_usage, sw.temp_celsius),
                    level: NotificationLevel::Success,
                });
            }
            Err(e) => {
                let sanitized = crate::provider::LogSanitizer::sanitize_error(&e);
                self.notification = Some(Notification {
                    message: format!("Failed to sync {host}: {sanitized}"),
                    level: NotificationLevel::Error,
                });
            }
        }
    }
}

