fn test_cisco_ios_xe_parsers() {
    // 1. show version 48P
    let sys48 = parse_show_version(SHOW_VERSION_C9300_48P).expect("parse show version 48P");
    assert_eq!(sys48.hostname, "sw-idf1a-01");
