use std::collections::HashMap;
use std::path::{Path, PathBuf};
use crate::provider::sanitizer::LogSanitizer;

/// Safe command builder constructing strict argument arrays for ansible-playbook
/// execution without shell interpolation.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct AnsibleCommandBuilder {
    pub binary: PathBuf,
    pub playbook_path: PathBuf,
    pub inventory_path: PathBuf,
    pub limit: Option<String>,
    pub check_mode: bool,
    pub diff_mode: bool,
    pub verbosity: u8,
    pub extra_vars: HashMap<String, String>,
}

impl AnsibleCommandBuilder {
    pub fn new(playbook_path: impl AsRef<Path>, inventory_path: impl AsRef<Path>) -> Self {
        Self {
            binary: PathBuf::from("ansible-playbook"),
            playbook_path: playbook_path.as_ref().to_path_buf(),
            inventory_path: inventory_path.as_ref().to_path_buf(),
            limit: None,
            check_mode: false,
            diff_mode: false,
            verbosity: 1,
            extra_vars: HashMap::new(),
        }
    }

    pub fn with_binary(mut self, binary: impl AsRef<Path>) -> Self {
        self.binary = binary.as_ref().to_path_buf();
        self
    }

    pub fn with_limit(mut self, limit: impl Into<String>) -> Self {
        self.limit = Some(limit.into());
        self
    }

    pub fn with_check_mode(mut self, check: bool) -> Self {
        self.check_mode = check;
        self
    }

    pub fn with_diff_mode(mut self, diff: bool) -> Self {
        self.diff_mode = diff;
        self
    }

    pub fn with_verbosity(mut self, verbosity: u8) -> Self {
        self.verbosity = verbosity;
        self
    }

    pub fn with_extra_var(mut self, key: impl Into<String>, value: impl Into<String>) -> Self {
        self.extra_vars.insert(key.into(), value.into());
        self
    }

    /// Construct a pure vector of arguments for direct `std::process::Command::args` execution.
    /// This eliminates any shell quoting or interpolation vulnerabilities.
    pub fn build_args(&self) -> Vec<String> {
        let mut args = Vec::new();

        // 1. Inventory specification
        args.push("-i".to_string());
        args.push(self.inventory_path.display().to_string());

        // 2. Target limitation
        if let Some(ref limit) = self.limit {
            if !limit.trim().is_empty() {
                args.push("--limit".to_string());
                args.push(limit.clone());
            }
        }

        // 3. Dry-run / Check & Diff modes
        if self.check_mode {
            args.push("--check".to_string());
        }
        if self.diff_mode {
            args.push("--diff".to_string());
        }

        // 4. Verbosity level
        if self.verbosity == 1 {
            args.push("-v".to_string());
        } else if self.verbosity == 2 {
            args.push("-vv".to_string());
        } else if self.verbosity >= 3 {
            args.push("-vvv".to_string());
        }

        // 5. Extra variables (JSON formatted if present)
        if !self.extra_vars.is_empty() {
            if let Ok(json_str) = serde_json::to_string(&self.extra_vars) {
                args.push("--extra-vars".to_string());
                args.push(json_str);
            }
        }

        // 6. Playbook target path (last positional argument)
        args.push(self.playbook_path.display().to_string());

        args
    }

    /// Construct a human-readable, secret-sanitized command representation for audit logs.
    pub fn build_sanitized_display(&self) -> String {
        let args = self.build_args();
        let binary_str = self.binary.display().to_string();
        let full_command = format!("{binary_str} {}", args.join(" "));
        LogSanitizer::sanitize(&full_command)
    }
}

use std::collections::HashMap;
use std::path::Path;
use std::process::{Command, Stdio};
use std::sync::Mutex;
use std::time::{Duration, Instant};

#[derive(Debug, thiserror::Error)]
pub enum SubprocessError {
    #[error("Failed to spawn process '{program}': {source}")]
    SpawnFailed {
        program: String,
        source: std::io::Error,
    },
    #[error("Process '{program}' execution failed: {source}")]
    ExecutionFailed {
        program: String,
        source: std::io::Error,
    },
    #[error("Subprocess timed out after {0:?}")]
    TimedOut(Duration),
}

/// Output captured from a subprocess execution.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct SubprocessOutput {
    pub exit_code: i32,
    pub stdout: String,
    pub stderr: String,
    pub duration: Duration,
    pub timed_out: bool,
}

impl SubprocessOutput {
    pub fn success(stdout: impl Into<String>, duration: Duration) -> Self {
        Self {
            exit_code: 0,
            stdout: stdout.into(),
            stderr: String::new(),
            duration,
            timed_out: false,
        }
    }

    pub fn failure(code: i32, stdout: impl Into<String>, stderr: impl Into<String>, duration: Duration) -> Self {
        Self {
            exit_code: code,
            stdout: stdout.into(),
            stderr: stderr.into(),
            duration,
            timed_out: false,
        }
    }
}

/// Trait abstracting subprocess execution to allow mock-backed tests and development.
pub trait SubprocessRunner: Send + Sync {
    fn run(
        &self,
        program: &Path,
        args: &[String],
        env: &HashMap<String, String>,
        timeout: Duration,
    ) -> Result<SubprocessOutput, SubprocessError>;
}

/// Real subprocess execution engine using `std::process::Command` with argument arrays.
pub struct ProcessSubprocessRunner;

impl SubprocessRunner for ProcessSubprocessRunner {
    fn run(
        &self,
        program: &Path,
        args: &[String],
        env: &HashMap<String, String>,
        timeout: Duration,
    ) -> Result<SubprocessOutput, SubprocessError> {
        let start = Instant::now();

        // 1. Direct argument array execution without shell wrapping
        let mut cmd = Command::new(program);
        cmd.args(args);
        cmd.envs(env);
        cmd.stdout(Stdio::piped());
        cmd.stderr(Stdio::piped());

        let mut child = cmd.spawn().map_err(|e| SubprocessError::SpawnFailed {
            program: program.display().to_string(),
            source: e,
        })?;

        // 2. Timeout polling loop
        let poll_interval = Duration::from_millis(50);
        let mut timed_out = false;

        loop {
            match child.try_wait() {
                Ok(Some(status)) => {
                    let output = child.wait_with_output().map_err(|e| SubprocessError::ExecutionFailed {
                        program: program.display().to_string(),
                        source: e,
                    })?;
                    let duration = start.elapsed();
                    let stdout = String::from_utf8_lossy(&output.stdout).to_string();
                    let stderr = String::from_utf8_lossy(&output.stderr).to_string();
                    let exit_code = status.code().unwrap_or(if status.success() { 0 } else { 1 });

                    return Ok(SubprocessOutput {
                        exit_code,
                        stdout,
                        stderr,
                        duration,
                        timed_out: false,
                    });
                }
                Ok(None) => {
                    if start.elapsed() >= timeout {
                        timed_out = true;
                        let _ = child.kill();
                        let _ = child.wait();
                        break;
                    }
                    std::thread::sleep(poll_interval);
                }
                Err(e) => {
                    return Err(SubprocessError::ExecutionFailed {
                        program: program.display().to_string(),
                        source: e,
                    });
                }
            }
        }

        let duration = start.elapsed();
        Ok(SubprocessOutput {
            exit_code: 124, // Standard timeout exit code
            stdout: String::new(),
            stderr: format!("Process timed out after {timeout:?}"),
            duration,
            timed_out,
        })
    }
}

/// Mock subprocess runner delivering realistic Ansible playbook results
/// without executing external binaries or touching physical network devices.
pub struct MockSubprocessRunner {
    pub simulated_timeout: Mutex<Option<Duration>>,
    pub simulated_exit_code: Mutex<Option<i32>>,
    pub custom_responses: Mutex<HashMap<String, String>>,
}

impl Default for MockSubprocessRunner {
    fn default() -> Self {
        Self::new()
    }
}

impl MockSubprocessRunner {
    pub fn new() -> Self {
        Self {
            simulated_timeout: Mutex::new(None),
            simulated_exit_code: Mutex::new(None),
            custom_responses: Mutex::new(HashMap::new()),
        }
    }

    pub fn set_timeout(&self, timeout: Option<Duration>) {
        *self.simulated_timeout.lock().unwrap() = timeout;
    }

    pub fn set_exit_code(&self, code: Option<i32>) {
        *self.simulated_exit_code.lock().unwrap() = code;
    }

    pub fn set_response(&self, playbook: impl Into<String>, stdout: impl Into<String>) {
        self.custom_responses.lock().unwrap().insert(playbook.into(), stdout.into());
    }
}

impl SubprocessRunner for MockSubprocessRunner {
    fn run(
        &self,
        _program: &Path,
        args: &[String],
        _env: &HashMap<String, String>,
        _timeout: Duration,
    ) -> Result<SubprocessOutput, SubprocessError> {
        let duration = Duration::from_millis(120);

        // Check simulated timeout
        if let Some(t) = *self.simulated_timeout.lock().unwrap() {
            return Ok(SubprocessOutput {
                exit_code: 124,
                stdout: String::new(),
                stderr: format!("Process timed out after {t:?}"),
                duration: t,
                timed_out: true,
            });
        }

        // Check simulated exit code
        if let Some(code) = *self.simulated_exit_code.lock().unwrap() {
            return Ok(SubprocessOutput::failure(
                code,
                "PLAY [Mock Execution Failed]\nTASK [Mock Task] fatal: [sw-idf1a-01.hq.net]: FAILED! => {\"msg\": \"Simulated failure\"}\n\nPLAY RECAP *********************************************************************\nsw-idf1a-01.hq.net : ok=1 changed=0 unreachable=0 failed=1 skipped=0 rescued=0 ignored=0",
                "Ansible execution returned non-zero code",
                duration,
            ));
        }

        // Extract playbook name and targets from args
        let playbook_arg = args.last().cloned().unwrap_or_default();
        let is_check_mode = args.iter().any(|a| a == "--check");

        // Check custom responses
        if let Some(custom) = self.custom_responses.lock().unwrap().get(&playbook_arg) {
            return Ok(SubprocessOutput::success(custom.clone(), duration));
        }

        // Extract targets from --limit
        let mut target_hosts = vec!["sw-idf1a-01.hq.net".to_string()];
        if let Some(limit_idx) = args.iter().position(|a| a == "--limit") {
            if let Some(limit_val) = args.get(limit_idx + 1) {
                target_hosts = limit_val.split(',').map(|s| s.trim().to_string()).collect();
            }
        }

        // Generate realistic deterministic output
        let mode_desc = if is_check_mode { "[DRY-RUN / CHECK MODE]" } else { "[LIVE RUN]" };
        let mut out = format!(
            "PLAY [IDF Switch Infrastructure Automation] **********************************\n\
             TASK [Gathering Facts] *********************************************************\n"
        );

        for host in &target_hosts {
            out.push_str(&format!("ok: [{host}]\n"));
        }

        out.push_str(&format!(
            "\nTASK [Execute Automation Workflow {mode_desc}] ************************\n"
        ));

        for host in &target_hosts {
            if is_check_mode {
                out.push_str(&format!("changed: [{host}] => (item=check_diff_verified)\n"));
            } else {
                out.push_str(&format!("changed: [{host}] => (item=config_applied)\n"));
            }
        }

        out.push_str("\nPLAY RECAP *********************************************************************\n");
        for host in &target_hosts {
            if is_check_mode {
                out.push_str(&format!("{host:<28} : ok=2    changed=1    unreachable=0    failed=0    skipped=0    rescued=0    ignored=0\n"));
            } else {
                out.push_str(&format!("{host:<28} : ok=2    changed=1    unreachable=0    failed=0    skipped=0    rescued=0    ignored=0\n"));
            }
        }

        Ok(SubprocessOutput::success(out, duration))
    }
}

