/// Validates a requested playbook filename or relative path against security constraints.
pub fn validate_path(&self, requested: &str) -> Result<PathBuf, PlaybookSecurityError> {
    let trimmed = requested.trim();
    if trimmed.is_empty() {
        return Err(PlaybookSecurityError::EmptyPath);
    }

    // 1. Disallow directory traversal markers
    if trimmed.contains("..") || trimmed.contains('\\') || trimmed.contains('\0') {
        return Err(PlaybookSecurityError::DirectoryTraversal {
            path: trimmed.to_string(),
        });
    }

    // 2. Validate file extension
    let path = Path::new(trimmed);
    match path.extension().and_then(|ext| ext.to_str()) {
        Some("yml") | Some("yaml") => {}
        _ => {
            return Err(PlaybookSecurityError::InvalidExtension {
                path: trimmed.to_string(),
            });
        }
    }

    // 3. Extract pure filename to verify whitelist approval
    let filename = path
        .file_name()
        .and_then(|f| f.to_str())
        .unwrap_or(trimmed);

    let approved = self
        .approved_playbooks
        .iter()
        .any(|pb| pb.filename == filename || pb.id == trimmed || pb.name == trimmed);

    if !approved {
        return Err(PlaybookSecurityError::NotApproved {
            name: trimmed.to_string(),
        });
    }

    // 4. Construct target within trusted root
    let resolved = self.trusted_root.join(filename);
    if !resolved.starts_with(&self.trusted_root) {
        return Err(PlaybookSecurityError::PathEscapesRoot {
            path: resolved.display().to_string(),
            root: self.trusted_root.display().to_string(),
        });
    }

    Ok(resolved)
}

